gjb(){return"\u0415\u0441\u0442\u044c \u0432\u043e\u043f\u0440\u043e\u0441, \u043d\u0430\u0448\u043b\u0438 \u043e\u0448\u0438\u0431\u043a\u0443 \u0438\u043b\u0438 \u043f\u043e\u044f\u0432\u0438\u043b\u0430\u0441\u044c \u0438\u0434\u0435\u044f \u0434\u043b\u044f \u041f\u0430\u043d\u0434\u0438? \u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u043d\u0430\u043c \u043d\u0438\u0436\u0435 \u2014 \u043c\u044b \u0447\u0438\u0442\u0430\u0435\u043c \u043a\u0430\u0436\u0434\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435."},
